import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join, relative, sep } from 'node:path';
import { repoRoot } from '../../lib/arena/repo-root.mjs';

export const BANNER =
  '/* GENERATED by scripts/build/react/build-demos.mjs — edit the source sibling, not this file.\n'
  + ' * Bun.Transpiler, classic JSX (React.createElement). See build-demos.mjs\n'
  + ' * for the full rationale. */\n';

export const ROOTS = ['frameworks/react/components', 'frameworks/react/ui-kits/console'];

export const SOURCE_EXTENSIONS = ['.jsx', '.tsx'];

export function loaderFor(path) {
  return path.endsWith('.tsx') || path.endsWith('.ts') ? 'tsx' : 'jsx';
}

export function findSourceFiles(dir) {
  const found = [];
  const walk = (d) => {
    for (const entry of readdirSync(d, { withFileTypes: true })) {
      const path = join(d, entry.name);
      if (entry.isDirectory()) walk(path);
      else if (SOURCE_EXTENSIONS.some((e) => entry.name.endsWith(e)) && !entry.name.includes('.test.')) found.push(path);
    }
  };
  walk(dir);
  return found.sort();
}

export function rewriteRelativeSourceImports(code) {
  return code.replace(/(from\s*")(\.\.?\/[^"]+?)\.[jt]sx"/g, '$1$2.generated.js"');
}

export function outputPathFor(relPath) {
  return relPath.replace(/\.[jt]sx$/, '.generated.js');
}

export async function buildDemos(opts = {}) {
  const root = opts.root ?? repoRoot;
  const tsconfig = JSON.stringify({ compilerOptions: { jsx: 'react' } });
  const transpilers = new Map(
    SOURCE_EXTENSIONS.map((e) => [loaderFor(e), new Bun.Transpiler({ loader: loaderFor(e), tsconfig })]),
  );

  const files = new Map();
  for (const treeRoot of ROOTS) {
    for (const absPath of findSourceFiles(join(root, treeRoot))) {
      const source = readFileSync(absPath, 'utf8');
      const compiled = transpilers.get(loaderFor(absPath)).transformSync(source);
      const rewritten = rewriteRelativeSourceImports(compiled);
      const outRel = outputPathFor(relative(root, absPath)).split(sep).join('/');
      if (files.has(outRel))
        throw new Error(`build-demos: ${outRel} is written by two sources at once; a .jsx and a .tsx `
          + 'of the same stem compile to one sibling and the second would overwrite the first');
      files.set(outRel, BANNER + rewritten);
    }
  }
  return files;
}

async function main() {
  const files = await buildDemos();
  for (const [outRel, content] of files) {
    writeFileSync(join(repoRoot, outRel), content);
    console.log(`wrote ${outRel}`);
  }
  console.log(`build-demos: ${files.size} file(s) compiled`);
}

if (import.meta.main) await main();
